// src/jsx/PrivateChat.jsx
import React, { useEffect, useState, useRef } from "react";
import { db } from "../js/firebaseConfig";
import {
    collection,
    addDoc,
    serverTimestamp,
    query,
    orderBy,
    onSnapshot,
    doc,
    setDoc,
    getDoc
} from "firebase/firestore";
import useSearchUsers from "../hooks/useSearchUsers";

function makeRoomId(a, b) {
    return [a, b].sort().join("_");
}

function getInitials(nameOrEmail) {
    if (!nameOrEmail) return "?";
    const parts = nameOrEmail.split(" ");
    if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
    return (parts[0][0] + parts[1][0]).toUpperCase();
}

function Avatar({ user, size = 40 }) {
    const style = {
        width: size,
        height: size,
        borderRadius: size / 2,
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        fontWeight: 700,
        fontSize: Math.max(12, size / 3),
        background: "#ddd",
        overflow: "hidden"
    };

    if (!user) return <div style={style}>{getInitials("U")}</div>;

    if (user.avatarUrl) {
        return <img src={user.avatarUrl} alt="avatar" style={{ ...style, objectFit: "cover" }} />;
    }

    const name = user.nome || user.email || "";
    return <div style={style}>{getInitials(name)}</div>;
}

export default function PrivateChat({ currentUser, otherUser, onClose }) {

    const roomId = makeRoomId(currentUser.uid, otherUser.id);
    const messagesRef = collection(db, `rooms/${roomId}/messages`);

    const { allUsers } = useSearchUsers();
    const [messages, setMessages] = useState([]);
    const [text, setText] = useState("");
    const listRef = useRef(null);

    useEffect(() => {

        // cria sala se não existir
        const roomDocRef = doc(db, "rooms", roomId);
        getDoc(roomDocRef).then(snap => {
            if (!snap.exists()) {
                setDoc(roomDocRef, {
                    members: [currentUser.uid, otherUser.id],
                    createdAt: serverTimestamp(),
                    lastMessage: ""
                });
            }
        });

        // listener
        const q = query(messagesRef, orderBy("createdAt", "asc"));
        const unsub = onSnapshot(q, snap => {
            setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));

            setTimeout(() => {
                if (listRef.current) listRef.current.scrollTop = listRef.current.scrollHeight;
            }, 100);
        });

        return () => unsub();

    }, [roomId]);

    const send = async () => {
        if (!text.trim()) return;

        await addDoc(messagesRef, {
            text,
            from: currentUser.uid,
            createdAt: serverTimestamp()
        });

        // atualizar sala
        await setDoc(doc(db, "rooms", roomId), {
            lastMessage: text,
            lastUpdated: serverTimestamp()
        }, { merge: true });

        setText("");
    };

    const findUserById = (id) => allUsers?.find(u => u.id === id);

    const formatTime = (ts) => {
        if (!ts) return "";
        if (ts?.toDate) {
            const d = ts.toDate();
            return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
        }
        // fallback
        try {
            return new Date(ts).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
        } catch {
            return "";
        }
    };

    return (
        <>
            <div className="chat-header">
                <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                    <button onClick={onClose} style={{ background: "transparent", border: "none", color: "white", fontSize: 18 }}>
                        ←
                    </button>
                    <Avatar user={otherUser} size={44} />
                    <div>
                        <div style={{ fontWeight: 700 }}>{otherUser.nome || otherUser.email}</div>
                        <div style={{ fontSize: 12, opacity: 0.9 }}>{otherUser.email}</div>
                    </div>
                </div>
            </div>

            <div className="chat-box" ref={listRef}>
                {messages.map(m => {
                    const isMe = m.from === currentUser.uid;
                    const sender = findUserById(m.from);
                    return (
                        <div key={m.id} style={{ display: "flex", marginBottom: 8, alignItems: "flex-end", justifyContent: isMe ? "flex-end" : "flex-start" }}>
                            {!isMe && (
                                <div style={{ marginRight: 8 }}>
                                    <Avatar user={sender || otherUser} size={36} />
                                </div>
                            )}

                            <div style={{ maxWidth: "75%" }}>
                                <div className={`msg ${isMe ? "me" : "other"}`}>
                                    {m.text}
                                </div>
                                <div className="hora" style={{ textAlign: isMe ? "right" : "left" }}>
                                    {formatTime(m.createdAt)}
                                </div>
                            </div>

                            {isMe && <div style={{ width: 36, marginLeft: 8 }} />} {/* placeholder para alinhamento */}
                        </div>
                    );
                })}
            </div>

            <div className="chat-input">
                <input
                    value={text}
                    onChange={e => setText(e.target.value)}
                    placeholder="Mensagem..."
                />
                <button onClick={send}>Enviar</button>
            </div>
        </>
    );
}
